CREATE OR REPLACE FUNCTION function_name (
    p_param1 IN VARCHAR2
)
RETURN NUMBER
AS
    v_result NUMBER;
BEGIN
    SELECT COUNT(*)
    INTO v_result
    FROM table_name
    WHERE column = p_param1;

    RETURN v_result;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN 0;
    WHEN OTHERS THEN
        RAISE;
END;

