CREATE OR REPLACE PACKAGE package_name
AS
    -- Public constants
    c_status_active CONSTANT VARCHAR2(10) := 'ACTIVE';

    -- Public procedures
    PROCEDURE proc_name (
        p_param1 IN VARCHAR2,
        p_param2 OUT NUMBER
    );

    -- Public functions
    FUNCTION func_name (
        p_param1 IN VARCHAR2
    ) RETURN NUMBER;
END package_name;
/

CREATE OR REPLACE PACKAGE BODY package_name
AS
    -- Private variables
    g_initialized BOOLEAN := FALSE;

    -- Private procedures
    PROCEDURE initialize
    AS
    BEGIN
        g_initialized := TRUE;
    END initialize;

    -- Public procedures
    PROCEDURE proc_name (
        p_param1 IN VARCHAR2,
        p_param2 OUT NUMBER
    )
    AS
    BEGIN
        IF NOT g_initialized THEN
            initialize;
        END IF;

        -- Implementation here
        p_param2 := 0;
    END proc_name;

    -- Public functions
    FUNCTION func_name (
        p_param1 IN VARCHAR2
    )
    RETURN NUMBER
    AS
        v_result NUMBER;
    BEGIN
        -- Implementation here
        RETURN v_result;
    END func_name;
END package_name;
/

